// tb_crc16_beat.sv -- equivalence of the matrix-form crc16_beat (drop 0.41, generated by sim/gen_crc16_beat.py) and
//   crc16_beat_serial (the chain of crc16_word stages it replaced, tb/crc16_beat_serial.sv) at BW = 16 (the tile), 4 and 1.
//   Self-checking, for Verilator and Icarus (`make crc16`; `make verilator` runs it first):
//     random: NRAND vectors per BW of (crc_in, words, n) -- n = 0 and n = BW forced on every eighth vector each, otherwise
//             uniform in 0..BW; crc_in and the words from a xorshift64, so every simulator sees the same vectors
//     basis:  for every n in 0..BW, every unit vector of {crc_in, words} (16 + 32*BW of them). Both modules are linear in
//             {crc_in, words} for a fixed n (XOR networks, the matrix form with constant AND masks), so agreeing on a
//             basis is agreeing on every input: an exhaustive proof per BW, the random vectors the check against a
//             non-linear slip
//   The serial chain's n > BW reads past its stage array, so n stays in 0..BW. Prints one line per BW and
//   "RESULT: ALL PASS" or "RESULT: <n> MISMATCHES" (the make target fails on anything but ALL PASS).
`timescale 1ns/1ps
module tb_crc16_beat;
  localparam int NRAND = 20000;                   // random vectors per BW (60,000 in all)

  logic [63:0] rs = 64'h243F6A8885A308D3;          // xorshift64 state
  function automatic logic [31:0] rnd32();
    rs = rs ^ (rs << 13);
    rs = rs ^ (rs >> 7);
    rs = rs ^ (rs << 17);
    return rs[63:32];
  endfunction

  // the three pairs: new (matrix) and reference (serial) on the same inputs
  logic [15:0]     c16, c4, c1;
  logic [32*16-1:0] w16;
  logic [32*4-1:0] w4;
  logic [31:0]     w1;
  logic [4:0]      n16;
  logic [2:0]      n4;
  logic [0:0]      n1;
  logic [15:0]     got16, exp16, got4, exp4, got1, exp1;
  crc16_beat        #(.BW(16)) u_new16 (.crc_in(c16), .words(w16), .n(n16), .crc_out(got16));
  crc16_beat_serial #(.BW(16)) u_ref16 (.crc_in(c16), .words(w16), .n(n16), .crc_out(exp16));
  crc16_beat        #(.BW(4))  u_new4  (.crc_in(c4),  .words(w4),  .n(n4),  .crc_out(got4));
  crc16_beat_serial #(.BW(4))  u_ref4  (.crc_in(c4),  .words(w4),  .n(n4),  .crc_out(exp4));
  crc16_beat        #(.BW(1))  u_new1  (.crc_in(c1),  .words(w1),  .n(n1),  .crc_out(got1));
  crc16_beat_serial #(.BW(1))  u_ref1  (.crc_in(c1),  .words(w1),  .n(n1),  .crc_out(exp1));

  int errors = 0;
  int checks [3];                                  // per BW: 16, 4, 1
  int nzero [3];
  int nfull [3];

  task automatic compare(input int sel, input logic [15:0] got, input logic [15:0] exp, input int n);
    checks[sel] = checks[sel] + 1;
    if (n == 0) nzero[sel] = nzero[sel] + 1;
    if (n == ((sel == 0) ? 16 : (sel == 1) ? 4 : 1)) nfull[sel] = nfull[sel] + 1;
    if (got !== exp) begin
      errors = errors + 1;
      if (errors <= 8)
        $display("MISMATCH BW=%0d n=%0d: matrix %04h, serial %04h (crc_in %04h)", (sel == 0) ? 16 : (sel == 1) ? 4 : 1, n, got, exp,
                 (sel == 0) ? c16 : (sel == 1) ? c4 : c1);
    end
  endtask

  initial begin
    for (int s = 0; s < 3; s++) begin checks[s] = 0; nzero[s] = 0; nfull[s] = 0; end
    // random vectors, the three BW in step
    for (int v = 0; v < NRAND; v++) begin
      c16 = 16'(rnd32() >> 16); c4 = 16'(rnd32() >> 16); c1 = 16'(rnd32() >> 16);
      for (int k = 0; k < 16; k++) w16[32*k +: 32] = rnd32();
      for (int k = 0; k < 4; k++)  w4[32*k +: 32]  = rnd32();
      w1 = rnd32();
      case (v % 8)
        0: begin n16 = 5'd0;  n4 = 3'd0; n1 = 1'b0; end
        1: begin n16 = 5'd16; n4 = 3'd4; n1 = 1'b1; end
        default: begin n16 = 5'(rnd32() % 17); n4 = 3'(rnd32() % 5); n1 = 1'(rnd32() % 2); end
      endcase
      #1;
      compare(0, got16, exp16, int'(n16));
      compare(1, got4,  exp4,  int'(n4));
      compare(2, got1,  exp1,  int'(n1));
    end
    // basis sweep: every unit vector of {crc_in, words} for every n
    for (int n = 0; n <= 16; n++) begin
      for (int b = 0; b < 16 + 32 * 16; b++) begin
        {c16, w16} = '0;
        if (b < 32 * 16) w16[b] = 1'b1; else c16[b - 32 * 16] = 1'b1;
        n16 = 5'(n);
        #1;
        compare(0, got16, exp16, n);
      end
    end
    for (int n = 0; n <= 4; n++) begin
      for (int b = 0; b < 16 + 32 * 4; b++) begin
        {c4, w4} = '0;
        if (b < 32 * 4) w4[b] = 1'b1; else c4[b - 32 * 4] = 1'b1;
        n4 = 3'(n);
        #1;
        compare(1, got4, exp4, n);
      end
    end
    for (int n = 0; n <= 1; n++) begin
      for (int b = 0; b < 16 + 32; b++) begin
        {c1, w1} = '0;
        if (b < 32) w1[b] = 1'b1; else c1[b - 32] = 1'b1;
        n1 = 1'(n);
        #1;
        compare(2, got1, exp1, n);
      end
    end
    $display("tb_crc16_beat: BW=16 %0d vectors (%0d random + %0d basis; n=0 in %0d, n=16 in %0d)", checks[0], NRAND, checks[0] - NRAND, nzero[0], nfull[0]);
    $display("tb_crc16_beat: BW=4  %0d vectors (%0d random + %0d basis; n=0 in %0d, n=4 in %0d)", checks[1], NRAND, checks[1] - NRAND, nzero[1], nfull[1]);
    $display("tb_crc16_beat: BW=1  %0d vectors (%0d random + %0d basis; n=0 in %0d, n=1 in %0d)", checks[2], NRAND, checks[2] - NRAND, nzero[2], nfull[2]);
    if (errors == 0) $display("RESULT: ALL PASS (matrix crc16_beat == serial chain on %0d vectors)", checks[0] + checks[1] + checks[2]);
    else             $display("RESULT: %0d MISMATCHES", errors);
    $finish;
  end
endmodule
